using Microsoft.EntityFrameworkCore;

// Cosmos DB provider fixes for EF Core 9:
// 1. Discriminator property renamed from "Discriminator" to "$type" — preserve old name
// 2. id property no longer contains discriminator — preserve old format
// 3. Sync I/O no longer supported — use async equivalents

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve "Discriminator" for existing documents (default changed to "$type")
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve compound id format for existing documents
        // (EF Core 8 stored "Session|123", EF Core 9 now stores just "123")
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// Fix 3: Sync I/O throws in EF Core 9 Cosmos provider.
// All queries and SaveChanges must be async.
class CosmosQueryService
{
    // BEFORE (breaks in EF Core 9 — throws InvalidOperationException):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();

    // AFTER:
    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        return await db.Sessions.ToListAsync();
    }

    async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

